<body>
<main class="wrap">
  <h1>Simulator Deposito</h1>
  <p class="sub">Hitung pertumbuhan saldo deposito beserta bunga bersih setelah pajak.</p>

  <section class="card">
    <form id="form" class="grid" autocomplete="off">
      <label>Setoran awal (Rp)
        <input id="awal" type="number" min="0" step="100000" value="10000000">
