      <label>Setoran tambahan / bulan (Rp)
        <input id="tambahan" type="number" min="0" step="50000" value="500000">
      </label>
      <label>Bunga per tahun (%)
        <input id="bunga" type="number" min="0" step="0.01" value="6">
