  }
  .card h2 { margin: 0 0 6px; font-size: 18px; }
  .modal-text { margin: 0 0 12px; font-size: 13px; line-height: 1.45; color: var(--muted); }
  .modal-text b { color: var(--text); letter-spacing: .08em; }
  .stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 7px; margin: 0 0 10px; }
  .stat { background: #f1f3f5; border-radius: 10px; padding: 8px 2px; }
  .stat b { display: block; font-size: 19px; line-height: 1.1; }
  .stat span { display: block; font-size: 9px; letter-spacing: .04em; color: #6b7278; margin-top: 2px; }
  .hint { margin: 0 0 14px; font-size: 11.5px; color: #6b7278; }
  .actions { display: flex; gap: 8px; }
  .actions button {
    flex: 1;
    border-radius: 10px;
    padding: 11px 8px;
    font-family: inherit;
    font-size: 13.5px;
    font-weight: 700;
    cursor: pointer;
