  }
  .primary { background: var(--green); color: #fff; }
  .ghost { background: #fff; border-color: var(--line); color: var(--text); }
</style>
</head>
<body>
  <div class="app">
    <header>
      <h1>KATA 5</h1>
      <button id="statsBtn" class="icon-btn" type="button">Statistik</button>
    </header>

    <div id="board" class="board" aria-label="Papan tebakan"></div>
    <div id="message" class="message" role="status" aria-live="polite"></div>
    <div id="keyboard" class="keyboard" aria-label="Keyboard virtual"></div>
  </div>

  <div id="modal" class="modal hidden" role="dialog" aria-modal="true" aria-labelledby="modalTitle">
    <div class="card">
      <h2 id="modalTitle">Statistik</h2>
      <p id="modalText" class="modal-text"></p>
      <div class="stats">
        <div class="stat"><b id="stPlayed">0</b><span>MAIN</span></div>
        <div class="stat"><b id="stWins">0</b><span>MENANG</span></div>
        <div class="stat"><b id="stLosses">0</b><span>KALAH</span></div>
        <div class="stat"><b id="stStreak">0</b><span>RUNTUN</span></div>
      </div>
      <p class="hint" id="stMax">Runtun kemenangan terbaik: 0</p>
      <div class="actions">
        <button id="playAgain" class="primary" type="button">Main Lagi</button>
        <button id="closeModal" class="ghost" type="button">Tutup</button>
      </div>
    </div>
  </div>

<script>
(function () {
  'use strict';

  var WORDS = [
    'bunga', 'rumah', 'pintu', 'kursi', 'lampu', 'taman', 'hutan', 'sawah', 'jalan', 'mobil',
    'kapal', 'angin', 'hujan', 'panas', 'bulan', 'tanah', 'pasir', 'pohon', 'jeruk', 'salak',
    'mulut', 'tenda', 'badan', 'darah', 'kulit', 'garam', 'telur', 'sayur', 'dapur', 'gelas',
    'pisau', 'tikar', 'kasur', 'kamar', 'kunci', 'murid', 'kelas', 'papan', 'huruf', 'angka',
    'waktu', 'tahun', 'siang', 'malam', 'detik', 'menit', 'cepat', 'besar', 'kecil', 'lebar',
    'berat', 'dekat', 'kanan', 'bawah', 'depan', 'dalam', 'akhir', 'sedih', 'marah', 'takut',
    'cinta', 'kasih', 'teman', 'kawan', 'kakak', 'orang', 'kerja', 'tidur', 'makan', 'minum',
    'duduk', 'tulis', 'lihat', 'tutup', 'mulai', 'pergi', 'pasar', 'harga', 'bayar', 'usaha',
    'kebun', 'gajah', 'tikus', 'lebah', 'semut', 'lalat', 'cicak', 'katak', 'buaya', 'penyu',
    'pulau', 'sakit', 'sehat', 'benar', 'salah', 'buruk', 'jelek', 'kotor', 'wangi', 'suara',
    'bunyi', 'musik', 'warna', 'merah', 'hijau', 'putih', 'hitam'
  ];

  var WORD_SET = new Set(WORDS);
  var ROWS = 6;
  var COLS = 5;
  var LS_KEY = 'kata5.stats.v1';
  var PRIORITY = { none: 0, gray: 1, yellow: 2, green: 3 };

  var boardEl = document.getElementById('board');
  var kbEl = document.getElementById('keyboard');
  var msgEl = document.getElementById('message');
  var modalEl = document.getElementById('modal');
  var modalTitle = document.getElementById('modalTitle');
  var modalText = document.getElementById('modalText');
  var playAgainBtn = document.getElementById('playAgain');
  var closeBtn = document.getElementById('closeModal');
  var statsBtn = document.getElementById('statsBtn');
  var stPlayed = document.getElementById('stPlayed');
  var stWins = document.getElementById('stWins');
  var stLosses = document.getElementById('stLosses');
  var stStreak = document.getElementById('stStreak');
  var stMax = document.getElementById('stMax');

  var rows = [];
  var keyEls = {};
  var answer = '';
  var guesses = [];
  var current = '';
  var busy = false;
  var gameOver = false;
  var msgTimer = null;

  /* ---------- penyimpanan statistik (aman terhadap error) ---------- */
  function defaultStats() {
    return { played: 0, wins: 0, losses: 0, streak: 0, maxStreak: 0 };
  }

  function loadStats() {
    var def = defaultStats();
    try {
      var raw = window.localStorage.getItem(LS_KEY);
      if (!raw) return def;
      var parsed = JSON.parse(raw);
      if (!parsed || typeof parsed !== 'object') return def;
      return {
        played: Number(parsed.played) || 0,
        wins: Number(parsed.wins) || 0,
        losses: Number(parsed.losses) || 0,
        streak: Number(parsed.streak) || 0,
        maxStreak: Number(parsed.maxStreak) || 0
      };
    } catch (err) {
      return def;
    }
  }

  function saveStats(stats) {
    try {
      window.localStorage.setItem(LS_KEY, JSON.stringify(stats));
    } catch (err) {
      /* localStorage bisa diblokir; abaikan agar game tetap jalan */
    }
  }

  /* ---------- membangun papan ---------- */
  function buildBoard() {
    for (var r = 0; r < ROWS; r++) {
      var row = document.createElement('div');
      row.className = 'row';
      var tiles = [];
      for (var c = 0; c < COLS; c++) {
        var tile = document.createElement('div');
        tile.className = 'tile';
        row.appendChild(tile);
        tiles.push(tile);
      }
      boardEl.appendChild(row);
      rows.push(tiles);
    }
  }

  /* ---------- membangun keyboard virtual ---------- */
  var KEY_LAYOUT = [
    ['q', 'w', 'e', 'r', 't', 'y', 'u', 'i', 'o', 'p'],
    ['a', 's', 'd', 'f', 'g', 'h', 'j', 'k', 'l'],
    ['ENTER', 'z', 'x', 'c', 'v', 'b', 'n', 'm', 'BACK']
  ];

  function buildKeyboard() {
    KEY_LAYOUT.forEach(function (layoutRow) {
      var row = document.createElement('div');
      row.className = 'krow';
      layoutRow.forEach(function (label) {
        var btn = document.createElement('button');
        btn.type = 'button';
        if (label === 'ENTER') {
          btn.className = 'key wide';
          btn.textContent = 'KIRIM';
          btn.setAttribute('aria-label', 'Kirim tebakan');
          btn.dataset.key = 'ENTER';
        } else if (label === 'BACK') {
          btn.className = 'key wide';
          btn.textContent = '⌫';
          btn.setAttribute('aria-label', 'Hapus satu huruf');
          btn.dataset.key = 'BACK';
        } else {
          btn.className = 'key';
          btn.textContent = label;
          btn.dataset.key = label;
        }
        btn.dataset.state = 'none';
        btn.addEventListener('click', function () {
          handleKey(btn.dataset.key);
        });
        keyEls[label] = btn;
        row.appendChild(btn);
      });
      kbEl.appendChild(row);
    });
  }

  /* ---------- utilitas tampilan ---------- */
  function flash(text, ms) {
    msgEl.textContent = text || '';
    if (msgTimer) {
      clearTimeout(msgTimer);
      msgTimer = null;
    }
    if (text && ms) {
      msgTimer = setTimeout(function () {
        msgEl.textContent = '';
        msgTimer = null;
      }, ms);
    }
  }

  function shakeRow(tiles) {
    var row = tiles[0].parentNode;
    row.classList.remove('shake');
    void row.offsetWidth;
    row.classList.add('shake');
    setTimeout(function () { row.classList.remove('shake'); }, 450);
  }

  function paintCurrentRow() {
    if (guesses.length >= ROWS) return;
    var tiles = rows[guesses.length];
    for (var i = 0; i < COLS; i++) {
      tiles[i].textContent = current[i] || '';
      tiles[i].classList.toggle('filled', Boolean(current[i]));
    }
  }

  /* ---------- penilaian huruf (termasuk huruf dobel) ---------- */
  function evaluate(guess, target) {
    var result = new Array(COLS).fill('gray');
    var counts = {};
    var i, ch;

    for (i = 0; i < COLS; i++) {
      ch = target[i];
      counts[ch] = (counts[ch] || 0) + 1;
    }
    for (i = 0; i < COLS; i++) {
      if (guess[i] === target[i]) {
        result[i] = 'green';
        counts[guess[i]] -= 1;
      }
    }
    for (i = 0; i < COLS; i++) {
      if (result[i] === 'gray') {
        ch = guess[i];
        if (counts[ch] > 0) {
          result[i] = 'yellow';
          counts[ch] -= 1;
        }
      }
    }
    return result;
  }

  function updateKeyboard(guess, result) {
    for (var i = 0; i < COLS; i++) {
      var el = keyEls[guess[i]];
      if (!el) continue;
      var now = el.dataset.state || 'none';
      if (PRIORITY[result[i]] > PRIORITY[now]) {
        el.classList.remove('green', 'yellow', 'gray');
        el.classList.add(result[i]);
        el.dataset.state = result[i];
      }
    }
  }

  /* ---------- alur permainan ---------- */
  function addLetter(ch) {
    if (current.length >= COLS) return;
    current += ch;
    paintCurrentRow();
  }

  function backspace() {
    if (!current.length) return;
    current = current.slice(0, -1);
    paintCurrentRow();
  }

  function submitGuess() {
    if (current.length < COLS) {
      flash('Huruf belum lengkap — butuh 5 huruf.', 1800);
      shakeRow(rows[guesses.length]);
      return;
    }
    if (!WORD_SET.has(current)) {
      flash('Kata itu belum ada di kamus. Coba kata lain.', 1800);
      shakeRow(rows[guesses.length]);
      return;
    }

    var guess = current;
    var result = evaluate(guess, answer);
    var tiles = rows[guesses.length];

    guesses.push(guess);
    current = '';
    busy = true;

    for (var i = 0; i < COLS; i++) {
      (function (index) {
        setTimeout(function () {
          tiles[index].classList.add('flip');
          setTimeout(function () {
            tiles[index].classList.add(result[index]);
          }, 160);
        }, index * 180);
      })(i);
    }

    updateKeyboard(guess, result);

    var wait = COLS * 180 + 360;
    setTimeout(function () {
      busy = false;
      if (guess === answer) {
        finish(true);
      } else if (guesses.length === ROWS) {
        finish(false);
      }
    }, wait);
  }

  function handleKey(key) {
    if (busy || gameOver) return;
    if (key === 'ENTER') { submitGuess(); return; }
    if (key === 'BACK') { backspace(); return; }
    if (/^[a-z]$/.test(key)) { addLetter(key); }
  }

  function finish(win) {
    gameOver = true;
    var s = loadStats();
    s.played += 1;
    if (win) {
      s.wins += 1;
      s.streak += 1;
      if (s.streak > s.maxStreak) s.maxStreak = s.streak;
    } else {
      s.losses += 1;
      s.streak = 0;
    }
    saveStats(s);

    if (win) {
      flash('Mantap! "' + answer.toUpperCase() + '" berhasil ditebak.', 0);
    } else {
      flash('Kesempatan habis. Jawabannya: ' + answer.toUpperCase(), 0);
    }

    setTimeout(function () { openModal(win); }, 1100);
  }

  /* ---------- modal statistik ---------- */
  function openModal(kind) {
    var s = loadStats();
    stPlayed.textContent = s.played;
    stWins.textContent = s.wins;
    stLosses.textContent = s.losses;
    stStreak.textContent = s.streak;
    stMax.textContent = 'Runtun kemenangan terbaik: ' + s.maxStreak;

    if (kind === 'stats') {
      modalTitle.textContent = 'Statistik';
      modalText.textContent = 'Semua hasil permainan tersimpan di perangkat ini.';
      playAgainBtn.style.display = gameOver ? '' : 'none';
    } else if (kind === true) {
      modalTitle.textContent = 'Kamu Menang!';
      modalText.innerHTML = 'Kata yang benar: <b>' + answer.toUpperCase() + '</b>';
      playAgainBtn.style.display = '';
    } else {
      modalTitle.textContent = 'Belum Berhasil';
      modalText.innerHTML = 'Kata yang benar: <b>' + answer.toUpperCase() + '</b>';
      playAgainBtn.style.display = '';
    }
    modalEl.classList.remove('hidden');
  }

  function closeModal() {
    modalEl.classList.add('hidden');
  }

  /* ---------- mulai ulang ---------- */
  function newGame() {
    answer = WORDS[Math.floor(Math.random() * WORDS.length)];
    guesses = [];
    current = '';
    busy = false;
    gameOver = false;

    for (var r = 0; r < ROWS; r++) {
      for (var c = 0; c < COLS; c++) {
        var tile = rows[r][c];
        tile.textContent = '';
        tile.className = 'tile';
      }
    }

    Object.keys(keyEls).forEach(function (k) {
      var el = keyEls[k];
      el.classList.remove('green', 'yellow', 'gray');
      el.dataset.state = 'none';
    });

    flash('', 0);
    closeModal();
  }

  /* ---------- keyboard fisik ---------- */
  document.addEventListener('keydown', function (e) {
    if (e.metaKey || e.ctrlKey || e.altKey) return;

    if (!modalEl.classList.contains('hidden')) {
      if (e.key === 'Escape') closeModal();
      return;
    }

    if (e.key === 'Enter') {
      e.preventDefault();
      handleKey('ENTER');
    } else if (e.key === 'Backspace') {
      e.preventDefault();
      handleKey('BACK');
    } else if (/^[a-zA-Z]$/.test(e.key)) {
      handleKey(e.key.toLowerCase());
    }
  });

  /* ---------- event lain ---------- */
  statsBtn.addEventListener('click', function () { openModal('stats'); });
  closeBtn.addEventListener('click', closeModal);
  playAgainBtn.addEventListener('click', newGame);
  modalEl.addEventListener('click', function (e) {
    if (e.target === modalEl) closeModal();
  });

  /* ---------- inisialisasi ---------- */
  buildBoard();
  buildKeyboard();
  newGame();
})();
</script>
</body>
</html>
```

**Cek kebutuhan**
- **Game tebak kata 5 huruf mirip Wordle berbahasa Indonesia** → array `WORDS` berisi 107 kata Indonesia 5 huruf, logika `evaluate()` dan `submitGuess()`.
- **Daftar kata sendiri minimal 60 kata** → konstanta `WORDS` (107 kata) dan `WORD_SET` untuk validasi tebakan.
- **6 kesempatan** → `var ROWS = 6` pada `buildBoard()`, pengecekan `guesses.length === ROWS` di `submitGuess()`.
- **Warna hijau/kuning/abu-abu benar saat huruf dobel** → fungsi `evaluate()` memakai dua lintasan: hijau dulu (kurangi `counts`), lalu kuning hanya jika sisa `counts` masih ada.
- **Keyboard virtual di layar yang ikut berwarna** → `buildKeyboard()` + `updateKeyboard()` dengan prioritas `PRIORITY` (hijau > kuning > abu-abu).
- **Bisa ketik pakai keyboard laptop** → listener `document.addEventListener('keydown', ...)` yang memetakan Enter, Backspace, dan huruf a–z.
- **Statistik menang/kalah tersimpan** → `loadStats()`/`saveStats()` dengan kunci `kata5.stats.v1`, dipanggil di `finish()` dan ditampilkan lewat `openModal()`.
- **Akses localStorage dibungkus try/catch** → blok `try { ... } catch (err) { ... }` di dalam `loadStats()` dan `saveStats()`.
- **Responsif sampai 375 px** → variabel `--tile: clamp(44px, 13.5vw, 58px)`, tinggi tombol `clamp(42px, 11.5vw, 52px)`, dan `max-width: 520px` pada `.app`.
- **Tanpa library, font, gambar, atau file luar** → seluruh CSS dan JavaScript ditulis inline dalam satu file.

**Catatan teknis**
- Tebakan hanya diterima jika kata ada di kamus internal; kata di luar daftar ditolak dengan pesan dan animasi goyang.
- Warna keyboard tidak pernah “turun level” (hijau tidak berubah jadi kuning/abu-abu) karena memakai peta prioritas.
- Statistik menyimpan `played`, `wins`, `losses`, `streak`, dan `maxStreak`; jika localStorage diblokir, game tetap berjalan dengan statistik sementara di memori.

Berikut aplikasi manajemen perkara satu file yang siap dipakai, lengkap dengan pencarian, filter, daftar sidang 7 hari ke depan, penanda merah untuk sidang besok, dan penyimpanan localStorage.

```html
<!DOCTYPE html>
<html lang="id">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Manajemen Perkara — Kantor Advokat</title>
<style>
  *, *::before, *::after { box-sizing: border-box; }
  [hidden] { display: none !important; }

  body {
    margin: 0;
    background: #eef2f6;
    color: #1c2530;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    font-size: 15px;
    line-height: 1.5;
    -webkit-text-size-adjust: 100%;
  }

  .wrap { max-width: 1040px; margin: 0 auto; padding: 16px 14px 40px; }

  /* ---------- Header ---------- */
  header.app {
    background: linear-gradient(135deg, #1f4e79, #2d6ea8);
    color: #fff;
    padding: 18px 16px;
    border-radius: 14px;
    margin-bottom: 14px;
    box-shadow: 0 2px 10px rgba(31, 78, 121, .18);
  }
  header.app h1 { font-size: 19px; margin: 0 0 3px; letter-spacing: .2px; }
  header.app p { margin: 0; font-size: 12.5px; opacity: .88; }

  /* ---------- Panel ---------- */
  .panel {
    background: #fff;
    border: 1px solid #e2e8f0;
    border-radius: 14px;
    padding: 14px;
    margin-bottom: 14px;
    box-shadow: 0 1px 2px rgba(16, 24, 40, .04);
  }
  .panel-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    margin-bottom: 10px;
  }
  .panel-head h2 {
    font-size: 13px;
    margin: 0;
    text-transform: uppercase;
    letter-spacing: .7px;
    color: #334155;
  }
  .pill {
    background: #eaf2fa;
    color: #1f4e79;
    font-size: 12px;
    font-weight: 700;
    padding: 2px 10px;
    border-radius: 999px;
    white-space: nowrap;
  }

  /* ---------- Toolbar ---------- */
  .toolbar { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 12px; }
  .toolbar input[type="search"] { flex: 1 1 200px; min-width: 0; }
  .toolbar select { flex: 1 1 128px; min-width: 0; }
  .toolbar .btn { flex: 0 0 auto; }

  input[type="text"], input[type="search"], input[type="date"], select {
    width: 100%;
    min-width: 0;
    padding: 9px 11px;
    border: 1px solid #cbd5e1;
    border-radius: 9px;
    background: #fff;
    color: inherit;
    font: inherit;
    font-size: 14px;
  }
  input:focus-visible, select:focus-visible, button:focus-visible {
    outline: 2px solid #2d6ea8;
    outline-offset: 1px;
  }

  /* ---------- Buttons ---------- */
  .btn {
    border: 1px solid transparent;
    border-radius: 9px;
    padding: 9px 14px;
    font: inherit;
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    background: #eef2f6;
    color: #1c2530;
    white-space: nowrap;
  }
  .btn-primary { background: #1f4e79; color: #fff; }
  .btn-primary:hover { background: #17405f; }
  .btn-ghost { background: #fff; border-color: #cbd5e1; }
  .btn-ghost:hover { background: #f8fafc; }
  .btn-danger { background: #fff; border-color: #fda29b; color: #b42318; }
  .btn-danger:hover { background: #fef3f2; }
  .btn-sm { padding: 6px 12px; font-size: 13px; border-radius: 8px; }

  /* ---------- Sidang 7 hari ---------- */
  .sidang-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 8px; }
  .sidang-item {
    display: flex;
    gap: 12px;
    align-items: flex-start;
    padding: 10px 12px;
    border: 1px solid #e2e8f0;
    border-left: 4px solid #2d6ea8;
    border-radius: 10px;
    background: #fbfdff;
  }
  .sidang-item.besok {
    border-color: #fda29b;
    border-left-color: #d92d20;
    background: #fef3f2;
  }
  .sidang-tgl { flex: 0 0 auto; min-width: 96px; }
  .tgl { display: block; font-weight: 700; font-size: 13px; color: #1f4e79; }
  .sidang-item.besok .tgl { color: #b42318; }
  .selisih { display: inline-block; font-size: 12px; font-weight: 600; color: #475569; }
  .selisih.merah { color: #d92d20; }
  .sidang-isi { min-width: 0; }
  .sidang-nomor {
    margin: 0 0 2px;
    font-weight: 700;
    font-size: 13.5px;
    overflow-wrap: anywhere;
  }
  .sidang-meta { margin: 0; font-size: 12.5px; color: #64748b; overflow-wrap: anywhere; }

  @media (max-width: 520px) {
    .sidang-item { flex-direction: column; gap: 6px; }
    .sidang-tgl { min-width: 0; display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
    .tgl { display: inline; }
  }

  /* ---------- Daftar perkara ---------- */
  .grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    gap: 10px;
  }
  .card {
    border: 1px solid #e2e8f0;
    border-radius: 12px;
    padding: 12px;
    background: #fff;
    display: flex;
    flex-direction: column;
    gap: 8px;
  }
  .card.besok { border-color: #fda29b; background: #fffcfb; }
  .card-top {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    justify-content: space-between;
    align-items: flex-start;
  }
  .card-top h3 { font-size: 14px; margin: 0; overflow-wrap: anywhere; }
  .badges { display: flex; flex-wrap: wrap; gap: 4px; }
  .badge {
    display: inline-block;
    font-size: 11px;
    font-weight: 700;
    padding: 2px 8px;
    border-radius: 999px;
    letter-spacing: .3px;
  }
  .b-perdata { background: #e8f1fb; color: #1f4e79; }
  .b-pidana  { background: #fdecec; color: #b42318; }
  .b-tun     { background: #eafaf1; color: #067647; }
  .b-niaga   { background: #fdf3e2; color: #b54708; }
  .s-baru     { background: #eef2f6; color: #334155; }
  .s-berjalan { background: #e8f1fb; color: #1f4e79; }
  .s-ditunda  { background: #fdf3e2; color: #b54708; }
  .s-selesai  { background: #eafaf1; color: #067647; }

  .card dl { margin: 0; display: grid; gap: 5px; font-size: 13px; }
  .card dl > div { display: grid; grid-template-columns: 84px 1fr; gap: 6px; }
  .card dt { color: #64748b; }
  .card dd { margin: 0; overflow-wrap: anywhere; }
  .card-aksi {
    display: flex;
    gap: 8px;
    margin-top: auto;
    padding-top: 8px;
    border-top: 1px dashed #e2e8f0;
  }
  .muted { color: #64748b; }

  /* ---------- Form ---------- */
  .form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
  @media (max-width: 600px) { .form-grid { grid-template-columns: 1fr; } }
  .field { display: flex; flex-direction: column; gap: 4px; min-width: 0; }
  .field.full { grid-column: 1 / -1; }
  .field label { font-size: 12px; font-weight: 600; color: #475569; }
  .aksi { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 12px; }

  .pesan {
    margin: 10px 0 0;
    font-size: 13px;
    font-weight: 600;
    padding: 8px 11px;
    border-radius: 8px;
  }
  .pesan.ok { background: #eafaf1; color: #067647; }
  .pesan.error { background: #fef3f2; color: #b42318; }

  .kosong { color: #64748b; font-size: 13px; margin: 6px 0 0; }

  /* ---------- Footer ---------- */
  .kaki { text-align: center; font-size: 12px; color: #64748b; padding: 4px 0 0; }
  .kaki .peringatan { color: #b42318; font-weight: 600; }
</style>
</head>
<body>
<div class="wrap">

  <header class="app">
    <h1>Manajemen Perkara</h1>
    <p>Kantor Advokat Simatupang &amp; Rekan · data contoh fiktif</p>
  </header>

  <section class="panel" aria-labelledby="judulSidang">
    <div class="panel-head">
      <h2 id="judulSidang">Sidang 7 Hari ke Depan</h2>
      <span class="pill" id="hitungSidang">0</span>
    </div>
    <div id="daftarSidang"></div>
  </section>

  <section class="panel" aria-labelledby="judulPerkara">
    <div class="panel-head">
      <h2 id="judulPerkara">Daftar Perkara</h2>
      <span class="pill" id="hitungPerkara">0</span>
    </div>

    <div class="toolbar">
      <input type="search" id="cari" placeholder="Cari nomor, pihak, klien, pengadilan…" aria-label="Cari perkara">
      <select id="filterJenis" aria-label="Filter jenis perkara">
        <option value="">Semua jenis</option>
      </select>
      <select id="filterStatus" aria-label="Filter status perkara">
        <option value="">Semua status</option>
      </select>
      <button type="button" class="btn btn-ghost" id="btnReset">Reset</button>
    </div>

    <div class="grid" id="daftarPerkara"></div>
    <p class="kosong" id="kosongPerkara" hidden>Tidak ada perkara yang cocok dengan pencarian atau filter.</p>
  </section>

  <section class="panel" aria-labelledby="judulForm">
    <div class="panel-head">
      <h2 id="judulForm">Tambah Perkara</h2>
    </div>
    <form id="formPerkara" novalidate>
      <div class="form-grid">
        <div class="field full">
          <label for="fNomor">Nomor perkara</label>
          <input type="text" id="fNomor" placeholder="Contoh: 45/Pdt.G/2025/PN Jkt.Pst" autocomplete="off">
        </div>
        <div class="field">
          <label for="fJenis">Jenis</label>
          <select id="fJenis"></select>
        </div>
        <div class="field">
          <label for="fStatus">Status</label>
          <select id="fStatus"></select>
        </div>
        <div class="field">
          <label for="fPengadilan">Pengadilan</label>
          <input type="text" id="fPengadilan" placeholder="PN Jakarta Pusat" autocomplete="off">
        </div>
        <div class="field">
          <label for="fKlien">Klien</label>
          <input type="text" id="fKlien" placeholder="Nama klien" autocomplete="off">
        </div>
        <div class="field full">
          <label for="fPihak">Para pihak</label>
          <input type="text" id="fPihak" placeholder="Penggugat melawan Tergugat" autocomplete="off">
        </div>
        <div class="field full">
          <label for="fSidang">Jadwal sidang berikutnya</label>
          <input type="date" id="fSidang">
        </div>
      </div>

      <p class="pesan" id="pesan" hidden></p>

      <div class="aksi">
        <button type="submit" class="btn btn-primary">Simpan perkara</button>
        <button type="button" class="btn btn-ghost" id="btnBatal" hidden>Batal ubah</button>
      </div>
    </form>
  </section>

  <footer class="kaki">
    <span id="notifPenyimpanan">Data tersimpan otomatis di peramban ini (localStorage).</span>
  </footer>

</div>

<script>
(function () {
  'use strict';

  var KEY = 'perkara-advokat-v1';
  var JENIS = ['Perdata', 'Pidana', 'TUN', 'Niaga'];
  var STATUS = ['Baru', 'Berjalan', 'Ditunda', 'Selesai'];
  var HARI = ['Min', 'Sen', 'Sel', 'Rab', 'Kam', 'Jum', 'Sab'];
  var BULAN = ['Jan', 'Feb', 'Mar', 'Apr', 'Mei', 'Jun', 'Jul', 'Agu', 'Sep', 'Okt', 'Nov', 'Des'];

  var perkara = [];
  var editId = null;
  var penyimpananSiap = true;
  var timerPesan = null;

  /* ---------- Utilitas ---------- */

  function el(id) { return document.getElementById(id); }

  function isoDari(d) {
    return d.getFullYear() + '-' +
      String(d.getMonth() + 1).padStart(2, '0') + '-' +
      String(d.getDate()).padStart(2, '0');
  }

  function hariIni() {
    var d = new Date();
    d.setHours(0, 0, 0, 0);
    return d;
  }

  function geserHari(n) {
    var d = hariIni();
    d.setDate(d.getDate() + n);
    return isoDari(d);
  }

  function keTanggal(iso) {
    if (!iso || typeof iso !== 'string') return null;
    var p = iso.split('-');
    if (p.length !== 3) return null;
    var d = new Date(Number(p[0]), Number(p[1]) - 1, Number(p[2]));
    return isNaN(d.getTime()) ? null : d;
  }

  function selisihHari(iso) {
    var d = keTanggal(iso);
    if (!d) return null;
    d.setHours(0, 0, 0, 0);
    return Math.round((d - hariIni()) / 86400000);
  }

  function formatTanggal(iso) {
    var d = keTanggal(iso);
    if (!d) return '—';
    return HARI[d.getDay()] + ', ' + d.getDate() + ' ' + BULAN[d.getMonth()] + ' ' + d.getFullYear();
  }

  function labelSelisih(n) {
    if (n === null) return '';
    if (n === 0) return 'Hari ini';
    if (n === 1) return 'Besok';
    if (n > 1) return n + ' hari lagi';
    return Math.abs(n) + ' hari lalu';
  }

  function esc(s) {
    return String(s === null || s === undefined ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }

  function slug(s) {
    return String(s).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
  }

  /* ---------- Data contoh (fiktif) ---------- */

  function dataContoh() {
    return [
      { id: 'c1', nomor: '45/Pdt.G/2025/PN Jkt.Pst', jenis: 'Perdata', pengadilan: 'PN Jakarta Pusat',
        pihak: 'PT Sinar Abadi melawan PT Mitra Karya', klien: 'PT Sinar Abadi',
        status: 'Berjalan', sidang: geserHari(0) },

      { id: 'c2', nomor: '212/Pid.B/2025/PN Bdg', jenis: 'Pidana', pengadilan: 'PN Bandung',
        pihak: 'Terdakwa: R. Hutagalung', klien: 'R. Hutagalung',
        status: 'Berjalan', sidang: geserHari(1) },

      { id: 'c3', nomor: '18/G/2025/PTUN.Sby', jenis: 'TUN', pengadilan: 'PTUN Surabaya',
        pihak: 'Yayasan Cahaya Ilmu melawan Kepala Dinas Pendidikan', klien: 'Yayasan Cahaya Ilmu',
        status: 'Baru', sidang: geserHari(1) },

      { id: 'c4', nomor: '7/Pdt.Sus-Niaga/2025/PN Niaga Jkt.Pst', jenis: 'Niaga', pengadilan: 'PN Niaga Jakarta Pusat',
        pihak: 'CV Bumi Tekstil melawan PT Sandang Jaya', klien: 'CV Bumi Tekstil',
        status: 'Berjalan', sidang: geserHari(3) },

      { id: 'c5', nomor: '88/Pdt.G/2025/PN Smg', jenis: 'Perdata', pengadilan: 'PN Semarang',
        pihak: 'Siti Rahmawati melawan Hadi Purnomo', klien: 'Siti Rahmawati',
        status: 'Ditunda', sidang: geserHari(6) },

      { id: 'c6', nomor: '301/Pid.Sus/2025/PN Mdn', jenis: 'Pidana', pengadilan: 'PN Medan',
        pihak: 'Terdakwa: A. Simbolon', klien: 'A. Simbolon',
        status: 'Berjalan', sidang: geserHari(12) },

      { id: 'c7', nomor: '24/G/2024/PTUN.Jkt', jenis: 'TUN', pengadilan: 'PTUN Jakarta',
        pihak: 'PT Lintas Data melawan Badan Koordinasi Penanaman Modal', klien: 'PT Lintas Data',
        status: 'Selesai', sidang: geserHari(-14) },

      { id: 'c8', nomor: '15/Pdt.Sus-Niaga/2025/PN Niaga Sby', jenis: 'Niaga', pengadilan: 'PN Niaga Surabaya',
        pihak: 'PT Argo Nusantara melawan PT Laut Biru', klien: 'PT Argo Nusantara',
        status: 'Baru', sidang: '' }
    ];
  }

  /* ---------- Penyimpanan ---------- */

  function normalkan(p) {
    if (!p || typeof p !== 'object') return null;
    return {
      id: p.id ? String(p.id) : 'c' + Math.random().toString(36).slice(2, 10),
      nomor: String(p.nomor || ''),
      jenis: JENIS.indexOf(p.jenis) >= 0 ? p.jenis : 'Perdata',
      pengadilan: String(p.pengadilan || ''),
      pihak: String(p.pihak || ''),
      klien: String(p.klien || ''),
      status: STATUS.indexOf(p.status) >= 0 ? p.status : 'Baru',
      sidang: keTanggal(p.sidang) ? p.sidang : ''
    };
  }

  function muat() {
    try {
      var mentah = window.localStorage.getItem(KEY);
      if (mentah) {
        var data = JSON.parse(mentah);
        if (Array.isArray(data)) {
          perkara = data.map(normalkan).filter(function (x) { return x !== null; });
          return;
        }
      }
    } catch (e) {
      penyimpananSiap = false;
      if (window.console && console.warn) console.warn('localStorage tidak dapat dibaca:', e);
    }
    perkara = dataContoh();
    simpan();
  }

  function simpan() {
    try {
      window.localStorage.setItem(KEY, JSON.stringify(perkara));
      penyimpananSiap = true;
    } catch (e) {
      penyimpananSiap = false;
      if (window.console && console.warn) console.warn('localStorage tidak dapat ditulis:', e);
    }
    perbaruiNotif();
  }

  function perbaruiNotif() {
    var n = el('notifPenyimpanan');
    if (!n) return;
    if (penyimpananSiap) {
      n.className = '';
      n.textContent = 'Data tersimpan otomatis di peramban ini (localStorage).';
    } else {
      n.className = 'peringatan';
      n.textContent = 'Peringatan: localStorage tidak tersedia. Perubahan hanya berlaku selama halaman ini terbuka.';
    }
  }

  /* ---------- Render: sidang 7 hari ke depan ---------- */

  function renderSidang() {
    var wadah = el('daftarSidang');

    var items = perkara.filter(function (p) {
      if (!p.sidang || p.status === 'Selesai') return false;
      var s = selisihHari(p.sidang);
      return s !== null && s >= 0 && s <= 7;
    }).sort(function (a, b) {
      return a.sidang < b.sidang ? -1 : a.sidang > b.sidang ? 1 : 0;
    });

    el('hitungSidang').textContent = items.length;

    if (!items.length) {
      wadah.innerHTML = '<p class="kosong">Tidak ada sidang dalam 7 hari ke depan.</p>';
      return;
    }

    wadah.innerHTML = '<ul class="sidang-list">' + items.map(function (p) {
      var s = selisihHari(p.sidang);
      var besok = (s === 1);
      return '<li class="sidang-item' + (besok ? ' besok' : '') + '">' +
        '<div class="sidang-tgl">' +
          '<span class="tgl">' + esc(formatTanggal(p.sidang)) + '</span>' +
          '<span class="selisih' + (besok ? ' merah' : '') + '">' +
            (besok ? '● ' : '') + esc(labelSelisih(s)) +
          '</span>' +
        '</div>' +
        '<div class="sidang-isi">' +
          '<p class="sidang-nomor">' + esc(p.nomor) + '</p>' +
          '<p class="sidang-meta">' + esc(p.pengadilan) + ' · ' + esc(p.klien) +
            ' · <span class="badge b-' + slug(p.jenis) + '">' + esc(p.jenis) + '</span></p>' +
        '</div>' +
      '</li>';
    }).join('') + '</ul>';
  }

  /* ---------- Render: daftar perkara ---------- */

  function kartuPerkara(p) {
    var s = selisihHari(p.sidang);
    var besok = (s === 1);

    var jadwal;
    if (p.sidang) {
      jadwal = esc(formatTanggal(p.sidang)) +
        (s === null ? '' : ' <span class="selisih' + (besok ? ' merah' : '') + '">(' +
          esc(besok ? 'besok' : labelSelisih(s).toLowerCase()) + ')</span>');
    } else {
      jadwal = '<span class="muted">Belum dijadwalkan</span>';
    }

    return '<article class="card' + (besok ? ' besok' : '') + '">' +
      '<div class="card-top">' +
        '<h3>' + esc(p.nomor) + '</h3>' +
        '<div class="badges">' +
          '<span class="badge b-' + slug(p.jenis) + '">' + esc(p.jenis) + '</span>' +
          '<span class="badge s-' + slug(p.status) + '">' + esc(p.status) + '</span>' +
        '</div>' +
      '</div>' +
      '<dl>' +
        '<div><dt>Pengadilan</dt><dd>' + esc(p.pengadilan || '—') + '</dd></div>' +
        '<div><dt>Para pihak</dt><dd>' + esc(p.pihak || '—') + '</dd></div>' +
        '<div><dt>Klien</dt><dd>' + esc(p.klien || '—') + '</dd></div>' +
        '<div><dt>Sidang</dt><dd>' + jadwal + '</dd></div>' +
      '</dl>' +
      '<div class="card-aksi">' +
        '<button type="button" class="btn btn-sm btn-ghost" data-aksi="edit" data-id="' + esc(p.id) + '">Ubah</button>' +
        '<button type="button" class="btn btn-sm btn-danger" data-aksi="hapus" data-id="' + esc(p.id) + '">Hapus</button>' +
      '</div>' +
    '</article>';
  }

  function renderPerkara() {
    var q = el('cari').value.trim().toLowerCase();
    var fj = el('filterJenis').value;
    var fs = el('filterStatus').value;

    var items = perkara.filter(function (p) {
      if (fj && p.jenis !== fj) return false;
      if (fs && p.status !== fs) return false;
      if (q) {
        var teks = [p.nomor, p.pihak, p.klien, p.pengadilan].join(' ').toLowerCase();
        if (teks.indexOf(q) === -1) return false;
      }
      return true;
    }).sort(function (a, b) {
      var sa = a.sidang || '9999-99-99';
      var sb = b.sidang || '9999-99-99';
      if (sa < sb) return -1;
      if (sa > sb) return 1;
      return a.nomor < b.nomor ? -1 : a.nomor > b.nomor ? 1 : 0;
    });

    var total = perkara.length;
    el('hitungPerkara').textContent = (items.length === total)
      ? String(total)
      : items.length + ' / ' + total;

    el('daftarPerkara').innerHTML = items.map(kartuPerkara).join('');
    el('kosongPerkara').hidden = items.length > 0;
  }

  function render() {
    renderSidang();
    renderPerkara();
  }

  /* ---------- Pesan ---------- */

  function tampilPesan(teks, tipe) {
    var p = el('pesan');
    p.textContent = teks;
    p.className = 'pesan ' + (tipe || 'ok');
    p.hidden = false;
    if (timerPesan) window.clearTimeout(timerPesan);
    timerPesan = window.setTimeout(function () { p.hidden = true; }, 4000);
  }

  /* ---------- Aksi ---------- */

  function cariPerkara(id) {
    for (var i = 0; i < perkara.length; i++) {
      if (perkara[i].id === id) return perkara[i];
    }
    return null;
  }

  function resetForm() {
    el('formPerkara').reset();
    editId = null;
    el('judulForm').textContent = 'Tambah Perkara';
    el('btnBatal').hidden = true;
    el('formPerkara').querySelector('button[type="submit"]').textContent = 'Simpan perkara';
  }

  function mulaiEdit(id) {
    var p = cariPerkara(id);
    if (!p) return;

    editId = p.id;
    el('fNomor').value = p.nomor;
    el('fJenis').value = p.jenis;
    el('fPengadilan').value = p.pengadilan;
    el('fPihak').value = p.pihak;
    el('fKlien').value = p.klien;
    el('fStatus').value = p.status;
    el('fSidang').value = p.sidang || '';

    el('judulForm').textContent = 'Ubah Perkara';
    el('btnBatal').hidden = false;
    el('formPerkara').querySelector('button[type="submit"]').textContent = 'Simpan perubahan';
    el('pesan').hidden = true;

    var form = el('formPerkara');
    if (form.scrollIntoView) form.scrollIntoView({ behavior: 'smooth', block: 'start' });
    try { el('fNomor').focus({ preventScroll: true }); } catch (e) { el('fNomor').focus(); }
  }

  function hapusPerkara(id) {
    var p = cariPerkara(id);
    if (!p) return;
    if (!window.confirm('Hapus perkara ' + p.nomor + '?')) return;

    perkara = perkara.filter(function (x) { return x.id !== id; });
    if (editId === id) resetForm();
    simpan();
    render();
    tampilPesan('Perkara dihapus.', 'ok');
  }

  /* ---------- Isi pilihan select ---------- */

  function isiPilihan() {
    var fj = el('filterJenis'), fs = el('filterStatus');
    var fJenis = el('fJenis'), fStatus = el('fStatus');

    JENIS.forEach(function (j) {
      var a = document.createElement('option');
      a.value = j; a.textContent = j; fj.appendChild(a);

      var b = document.createElement('option');
      b.value = j; b.textContent = j; fJenis.appendChild(b);
    });

    STATUS.forEach(function (s) {
      var a = document.createElement('option');
      a.value = s; a.textContent = s; fs.appendChild(a);

      var b = document.createElement('option');
      b.value = s; b.textContent = s; fStatus.appendChild(b);
    });
  }

  /* ---------- Event ---------- */

  function bind() {
    el('cari').addEventListener('input', renderPerkara);
    el('filterJenis').addEventListener('change', renderPerkara);
    el('filterStatus').addEventListener('change', renderPerkara);

    el('btnReset').addEventListener('click', function () {
      el('cari').value = '';
      el('filterJenis').value = '';
      el('filterStatus').value = '';
      renderPerkara();
    });

    el('btnBatal').addEventListener('click', function () {
      resetForm();
      el('pesan').hidden = true;
    });

    document.addEventListener('click', function (e) {
      var tombol = e.target && e.target.closest ? e.target.closest('[data-aksi]') : null;
      if (!tombol) return;
      var id = tombol.getAttribute('data-id');
      if (tombol.getAttribute('data-aksi') === 'edit') {
        mulaiEdit(id);
      } else if (tombol.getAttribute('data-aksi') === 'hapus') {
        hapusPerkara(id);
      }
    });

    el('formPerkara').addEventListener('submit', function (e) {
      e.preventDefault();

      var nomor = el('fNomor').value.trim();
      var jenis = el('fJenis').value;
      var pengadilan = el('fPengadilan').value.trim();
      var pihak = el('fPihak').value.trim();
      var klien = el('fKlien').value.trim();
      var status = el('fStatus').value;
      var sidang = el('fSidang').value;

      if (!nomor || !klien) {
        tampilPesan('Nomor perkara dan nama klien wajib diisi.', 'error');
        (!nomor ? el('fNomor') : el('fKlien')).focus();
        return;
      }

      var kembar = perkara.some(function (p) {
        return p.id !== editId && p.nomor.toLowerCase() === nomor.toLowerCase();
      });
      if (kembar) {
        tampilPesan('Nomor perkara tersebut sudah terdaftar.', 'error');
        el('fNomor').focus();
        return;
      }

      var sedangEdit = editId !== null;

      if (sedangEdit) {
        var target = cariPerkara(editId);
        if (target) {
          target.nomor = nomor;
          target.jenis = jenis;
          target.pengadilan = pengadilan;
          target.pihak = pihak;
          target.klien = klien;
          target.status = status;
          target.sidang = sidang;
        }
      } else {
        perkara.push({
          id: 'c' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6),
          nomor: nomor,
          jenis: jenis,
          pengadilan: pengadilan,
          pihak: pihak,
          klien: klien,
          status: status,
          sidang: sidang
        });
      }

      simpan();
      render();
      resetForm();
      tampilPesan(sedangEdit ? 'Perkara berhasil diperbarui.' : 'Perkara baru berhasil ditambahkan.', 'ok');
    });
  }

  /* ---------- Inisialisasi ---------- */

  isiPilihan();
  muat();
  bind();
  render();
  perbaruiNotif();
})();
</script>
</body>
</html>
```

**Cek kebutuhan**

- **Setiap perkara punya nomor perkara, jenis (perdata, pidana, TUN, niaga), pengadilan, para pihak, klien, status, dan jadwal sidang berikutnya** → objek perkara pada `dataContoh()`, `normalkan()`, dan field `#fNomor`, `#fJenis`, `#fPengadilan`, `#fPihak`, `#fKlien`, `#fStatus`, `#fSidang` di `#formPerkara`
- **Pencarian** → input `#cari` dan penyaringan `q` di dalam `renderPerkara()`
- **Filter jenis dan status** → `#filterJenis` dan `#filterStatus` (diisi lewat `isiPilihan()`), dipakai di `renderPerkara()`
- **Daftar sidang 7 hari ke depan di bagian atas** → `renderSidang()` dengan `selisihHari()` bernilai 0–7, dirender ke `#daftarSidang` yang berada di panel pertama
- **Tanda merah untuk sidang besok** → kelas `besok` pada `renderSidang()` (`.sidang-item.besok`, `.selisih.merah`, penanda `●`) dan pada `kartuPerkara()`
- **Data tersimpan di localStorage** → `muat()`, `simpan()`, kunci `perkara-advokat-v1`, seluruh akses `localStorage` dibungkus `try/catch` dan dilaporkan lewat `perbaruiNotif()`
- **Data contoh fiktif** → `dataContoh()` berisi delapan perkara dengan tanggal sidang relatif terhadap hari ini
- **Responsif sampai 375 px** → `meta viewport`, `.toolbar` dengan `flex-wrap`, `.grid` `minmax(280px, 1fr)`, media query 520 px dan 600 px
- **Tanpa library, font, gambar, atau file luar** → seluruh CSS dan JavaScript tertulis inline di dalam file

**Catatan teknis**

- Tanggal contoh dibuat dinamis (`geserHari()`) agar daftar sidang 7 hari selalu terisi saat file dibuka kapan pun.
- Perhitungan selisih hari memakai tengah malam lokal, sehingga "besok" tidak terpengaruh jam akses.
- Perkara berstatus `Selesai` tidak dimunculkan di daftar sidang mendatang, tetapi tetap tampil di daftar perkara.
- Validasi menolak nomor perkara kosong, klien kosong, dan nomor perkara duplikat.
- Bila localStorage diblokir peramban, aplikasi tetap berjalan dan menampilkan peringatan di bagian bawah halaman.

