    background: rgba(34,197,94,.14); color: #4ade80; border: 1px solid rgba(34,197,94,.3);
  }
  .pill.warn { background: rgba(245,158,11,.14); color: #fbbf24; border-color: rgba(245,158,11,.35); }
  .pill.danger { background: rgba(239,68,68,.16); color: #f87171; border-color: rgba(239,68,68,.42); }

  .row {
    display: flex; justify-content: space-between; align-items: baseline;
    padding: 7px 9px; border-radius: 9px; background: #0c1524; margin-bottom: 6px;
    transition: background .2s;
  }
  .row:last-child { margin-bottom: 0; }
  .row-label { font-size: 12px; color: #8fa3c0; }
