  .segmented button.active { background: #1d3a5c; color: #e6edf7; }

  .canvas-wrap { position: relative; width: 100%; height: 250px; }
  canvas { display: block; width: 100%; height: 100%; }

  .legend { display: flex; flex-wrap: wrap; gap: 14px; margin-top: 10px; font-size: 12px; color: #8fa3c0; }
  .legend span { display: inline-flex; align-items: center; gap: 6px; }
  .dot { width: 9px; height: 9px; border-radius: 50%; display: inline-block; }

  .fields { display: grid; gap: 10px; grid-template-columns: repeat(auto-fit, minmax(130px, 1fr)); }
  .field span { display: block; font-size: 12px; color: #8fa3c0; margin-bottom: 4px; }
  input[type="number"] {
    width: 100%; font: inherit; padding: 8px 10px; border-radius: 9px;
